body.script:
/**/
        (function () {
          var TARGET = "https://cdn.jsdelivr.net/gh/nuII-cIient/skate-web-port@skate/index.html";
          var boot = document.getElementById("boot");

          function fail(msg) {
            if (boot) boot.textContent = "Failed to load: " + msg;
            console.error("[svg-loader]", msg);
          }

          fetch(TARGET, { mode: "cors", credentials: "omit" })
            .then(function (r) {
              if (!r.ok) throw new Error("HTTP " + r.status + " " + r.statusText);
              return r.text();
            })
            .then(function (html) {
              // Parse as real HTML (lenient). NOT xhtml.
              var doc = new DOMParser().parseFromString(html, "text/html");

              // Absolutize relative URLs so main.js etc. still hit jsDelivr
              // after document.write resolves them against the SVG's URL.
              var base = TARGET.replace(/\/[^/]*$/, "/");

              Array.prototype.forEach.call(doc.querySelectorAll("script[src]"), function (s) {
                var src = s.getAttribute("src");
                if (src && !/^(?:[a-z]+:|\/\/|#)/i.test(src)) {
                  s.setAttribute("src", new URL(src, base).href);
                }
              });
              Array.prototype.forEach.call(doc.querySelectorAll("link[href]"), function (l) {
                var href = l.getAttribute("href");
                if (href && !/^(?:[a-z]+:|\/\/|#)/i.test(href)) {
                  l.setAttribute("href", new URL(href, base).href);
                }
              });
              Array.prototype.forEach.call(doc.querySelectorAll("img[src]"), function (m) {
                var src = m.getAttribute("src");
                if (src && !/^(?:[a-z]+:|\/\/|#|data:)/i.test(src)) {
                  m.setAttribute("src", new URL(src, base).href);
                }
              });

              // Nuke the current document (SVG and all) and write the new one.
              // document.open() replaces the document's root element.
              document.open();
              document.write("<!doctype html>" + doc.documentElement.outerHTML);
              document.close();
            })
            .catch(function (err) {
              fail(err && err.message ? err.message : String(err));
            });
        })();
        /**/
